229	static void dijkstra_heap_sift_up(uint32_t * heap, uint32_t idx)
230	{
231	    while (idx > 0) {
232	        const uint32_t parent = (idx - 1u) / 2u;
233	        const uint32_t k_idx = dijkstra_key(heap[idx]);
234	        const uint32_t k_parent = dijkstra_key(heap[parent]);
235	
236	        if (k_idx >= k_parent) {
237	            break;
238	        }
239	        dijkstra_heap_swap(&heap[idx], &heap[parent]);
240	        idx = parent;
241	    }
242	}
243	
244	static void dijkstra_heap_sift_down(uint32_t * heap, uint32_t heap_sz, uint32_t idx)
245	{
246	    for (;;) {
247	        uint32_t smallest = idx;
248	        const uint32_t left = idx * 2u + 1u;
249	        const uint32_t right = left + 1u;
250	
251	        if (left < heap_sz && dijkstra_key(heap[left]) < dijkstra_key(heap[smallest])) {
252	            smallest = left;
253	        }
254	        if (right < heap_sz && dijkstra_key(heap[right]) < dijkstra_key(heap[smallest])) {
255	            smallest = right;
256	        }
257	        if (smallest == idx) {
258	            break;
259	        }
260	        dijkstra_heap_swap(&heap[idx], &heap[smallest]);
261	        idx = smallest;
262	    }
263	}
