279	    const uint32_t root = heap[0];
280	
281	    (*heap_sz)--;
282	    if (*heap_sz > 0) {
283	        heap[0] = heap[*heap_sz];
284	        dijkstra_heap_sift_down(heap, *heap_sz, 0);
285	    }
286	    return root;
