313	    const uint32_t * sources, uint32_t n_src,
314	    const uint32_t * targets, uint32_t n_dst,
315	    uint32_t * prev_out, uint32_t * out_src, uint32_t * out_dst,
316	    uint32_t * reachable_out)
317	{
318	    const uint32_t n = vmap_route_graph_node_count(graph);
319	    const uint32_t ecount = vmap_route_graph_edge_count(graph);
320	    uint32_t * dist = g_plan_scratch.dist;
321	    uint8_t * closed = g_plan_scratch.closed;
322	    uint32_t * heap = g_plan_scratch.heap;
323	    const uint32_t heap_cap = g_plan_scratch.heap_cap;
324	    uint32_t heap_sz = 0;
325	    uint32_t heap_peak = 0;
326	    bool ok = false;
327	    uint32_t reachable = 0;
328	
329	    if (!graph || n == 0 || !sources || n_src == 0 || !targets || n_dst == 0
330	        || !prev_out || !out_src || !out_dst || !dist || !closed || !heap) {
331	        return false;
332	    }
333	
334	    g_dij.dist = dist;
335	
336	    for (uint32_t i = 0; i < n; i++) {
337	        dist[i] = UINT32_MAX;
338	        prev_out[i] = UINT32_MAX;
339	        closed[i] = 0;
340	    }
341	
342	    for (uint32_t si = 0; si < n_src; si++) {
343	        const uint32_t s = sources[si];
344	
345	        if (s >= n) {
346	            continue;
347	        }
348	        if (dist[s] == UINT32_MAX) {
349	            dist[s] = 0;
350	            prev_out[s] = UINT32_MAX;
351	            (void)dijkstra_heap_push(heap, heap_cap, &heap_sz, s);
352	            if (heap_sz > heap_peak) {
353	                heap_peak = heap_sz;
354	            }
355	        }
356	    }
357	
358	    while (heap_sz > 0) {
359	        const uint32_t u = dijkstra_heap_pop(heap, &heap_sz);
360	        uint32_t adj_cnt;
361	        const uint32_t * adj;
362	
363	        if (u >= n || closed[u]) {
364	            continue;
365	        }
366	        closed[u] = 1;
367	        reachable++;
368	        if ((reachable & 31u) == 0u) {
369	            vmap_route_plan_yield();
370	            if (vmap_route_plan_aborted()) {
371	                ok = false;
372	                goto done;
373	            }
374	        }
375	
376	        for (uint32_t ti = 0; ti < n_dst; ti++) {
377	            if (targets[ti] < n && u == targets[ti]) {
378	                uint32_t cur = u;
379	
380	                *out_dst = u;
381	                while (cur != UINT32_MAX && cur < n
382	                    && prev_out[cur] != UINT32_MAX) {
383	                    cur = prev_out[cur];
384	                }
385	                *out_src = cur;
386	                ok = true;
387	                goto done;
388	            }
389	        }
390	
391	        if (dist[u] == UINT32_MAX) {
392	            continue;
393	        }
394	
395	        adj = vmap_route_graph_adj_edges(graph, u, &adj_cnt);
396	        if (!adj || adj_cnt == 0) {
397	            continue;
398	        }
399	
400	        for (uint32_t ai = 0; ai < adj_cnt; ai++) {
401	            const uint32_t ei = adj[ai];
402	            vmap_graph_edge_t e;
403	            uint32_t v;
404	            uint32_t w;
405	            uint32_t nd;
406	
407	            if (ei >= ecount) {
408	                continue;
409	            }
410	            if (!vmap_route_graph_edge(graph, ei, &e)) {
411	                continue;
412	            }
413	            v = vmap_route_graph_edge_other(&e, u);
414	            w = vmap_route_graph_edge_cost(&e);
415	            if (v >= n || w == UINT32_MAX || closed[v]) {
416	                continue;
417	            }
418	            if (w > UINT32_MAX - dist[u]) {
419	                continue;
420	            }
421	            nd = dist[u] + w;
422	            if (nd < dist[v]) {
423	                dist[v] = nd;
424	                prev_out[v] = u;
425	                (void)dijkstra_heap_push(heap, heap_cap, &heap_sz, v);
426	                if (heap_sz > heap_peak) {
427	                    heap_peak = heap_sz;
428	                }
429	            }
430	        }
431	    }
432	
433	done:
434	    if (ok && *out_dst < n) {
435	        VMAP_NAV_OUT("Dijkstra ok expanded=%lu g_cost=%u src_node=%u dst_node=%u heap_peak=%u/%u",
436	            (unsigned long)reachable, dist[*out_dst], *out_src, *out_dst,
437	            heap_peak, heap_cap);
438	    } else {
439	        VMAP_NAV_OUT("Dijkstra fail expanded=%lu/%u nodes heap_peak=%u/%u",
440	            (unsigned long)reachable, n, heap_peak, heap_cap);
441	    }
442	    if (reachable_out) {
443	        *reachable_out = reachable;
444	    }
445	    return ok;
446	}
