448	static bool route_find_edge(const vmap_route_graph_t * graph, uint32_t from,
449	    uint32_t to, vmap_graph_edge_t * out_edge)
450	{
451	    uint32_t adj_cnt;
452	    const uint32_t * adj;
453	    const uint32_t ecount = vmap_route_graph_edge_count(graph);
454	
455	    if (!graph || !out_edge || from >= vmap_route_graph_node_count(graph)) {
456	        return false;
457	    }
458	
459	    adj = vmap_route_graph_adj_edges(graph, from, &adj_cnt);
460	    if (!adj) {
461	        return false;
462	    }
463	
464	    for (uint32_t ai = 0; ai < adj_cnt; ai++) {
465	        const uint32_t ei = adj[ai];
466	        vmap_graph_edge_t e;
467	
468	        if (ei >= ecount) {
469	            continue;
470	        }
471	        if (!vmap_route_graph_edge(graph, ei, &e)) {
472	            continue;
473	        }
474	        if (vmap_route_graph_edge_other(&e, from) == to) {
475	            *out_edge = e;
476	            return true;
477	        }
478	    }
479	    return false;
480	}
