540	static vmap_maneuver_kind_t route_classify_turn(float turn_deg)
541	{
542	    const float a = fabsf(turn_deg);
543	
544	    if (a >= 150.0f) {
545	        return VMAP_MANEUVER_UTURN;
546	    }
547	    if (a >= 100.0f) {
548	        return turn_deg < 0.0f ? VMAP_MANEUVER_SHARP_LEFT : VMAP_MANEUVER_SHARP_RIGHT;
549	    }
550	    if (a >= 35.0f) {
551	        return turn_deg < 0.0f ? VMAP_MANEUVER_LEFT : VMAP_MANEUVER_RIGHT;
552	    }
553	    if (a >= 15.0f) {
554	        return turn_deg < 0.0f ? VMAP_MANEUVER_SLIGHT_LEFT
555	                               : VMAP_MANEUVER_SLIGHT_RIGHT;
556	    }
557	    return VMAP_MANEUVER_STRAIGHT;
558	}
