560	static void route_maneuver_set_plan_flags(vmap_route_maneuver_t * m,
561	    vmap_maneuver_kind_t kind, uint32_t out_degree,
562	    const char * in_name, const char * out_name)
563	{
564	    m->flags = 0;
565	    if (kind == VMAP_MANEUVER_START || kind == VMAP_MANEUVER_ARRIVE) {
566	        return;
567	    }
568	    if (out_degree >= 3u) {
569	        m->flags |= VMAP_MANEUVER_F_PLAN_JUNCTION;
570	        return;
571	    }
572	    if (in_name && out_name && in_name[0] != '\0' && out_name[0] != '\0'
573	        && strcmp(in_name, out_name) != 0) {
574	        m->flags |= VMAP_MANEUVER_F_PLAN_JUNCTION;
575	    }
576	}
