578	static void route_maneuver_put(vmap_route_maneuver_t * m,
579	    vmap_maneuver_kind_t kind, uint32_t node, double along_m, float turn_deg,
580	    const char * road_name, uint32_t out_degree, const char * in_name,
581	    const char * out_name)
582	{
583	    m->kind = kind;
584	    m->node = node;
585	    m->along_m = along_m;
586	    m->turn_deg = turn_deg;
587	    m->road_name = road_name;
588	    route_maneuver_set_plan_flags(m, kind, out_degree, in_name, out_name);
589	}
