591	static bool route_should_emit_maneuver(float turn_deg, uint32_t out_degree)
592	{
593	    const float a = fabsf(turn_deg);
594	
595	    if (a >= VMAP_ROUTE_MANEUVER_DEG) {
596	        return true;
597	    }
598	    if (out_degree >= 3u && a >= VMAP_ROUTE_MANEUVER_JUNCTION_DEG) {
599	        return true;
600	    }
601	    return false;
602	}
603	
604	static uint32_t route_build_maneuvers(vmap_route_graph_t * graph,
605	    const uint32_t * path_nodes, uint32_t path_len,
606	    double from_lon, double from_lat,
607	    vmap_route_maneuver_t * maneuvers, uint32_t cap)
608	{
609	    uint32_t count = 0;
610	    double along = 0.0;
611	
612	    if (!graph || !path_nodes || path_len < 2 || !maneuvers || cap == 0) {
613	        return 0;
614	    }
615	
616	    if (cap > 0) {
617	        route_maneuver_put(&maneuvers[count], VMAP_MANEUVER_START, path_nodes[0],
618	            0.0, 0.0f, NULL, 0, NULL, NULL);
619	        if (path_len >= 2) {
620	            vmap_graph_edge_t e;
621	
622	            if (route_find_edge(graph, path_nodes[0], path_nodes[1], &e)) {
623	                maneuvers[count].road_name =
624	                    vmap_route_graph_edge_name(graph, &e);
625	            }
626	        }
627	        count++;
628	    }
629	
630	    /* Turn at the first junction (path start node) using approach from plan origin. */
631	    if (path_len >= 2 && count < cap) {
632	        const uint32_t n0 = path_nodes[0];
633	        const uint32_t n1 = path_nodes[1];
634	        double lon0;
635	        double lat0;
636	        double lon1;
637	        double lat1;
638	        float in_brg;
639	        float out_brg;
640	        float turn_deg;
641	        vmap_graph_edge_t out_edge;
642	        const char * out_name = NULL;
643	        uint32_t out_degree;
644	        vmap_maneuver_kind_t kind;
645	
646	        vmap_route_graph_node_lonlat(graph, n0, &lon0, &lat0);
647	        vmap_route_graph_node_lonlat(graph, n1, &lon1, &lat1);
648	        in_brg = vmap_geo_bearing_deg(from_lon, from_lat, lon0, lat0);
649	        out_brg = vmap_geo_bearing_deg(lon0, lat0, lon1, lat1);
650	        turn_deg = vmap_geo_angle_delta_deg(in_brg, out_brg);
651	        out_degree = route_graph_out_degree(graph, n0);
652	
653	        if (route_find_edge(graph, n0, n1, &out_edge)) {
654	            out_name = vmap_route_graph_edge_name(graph, &out_edge);
655	        }
656	
657	        if (route_should_emit_maneuver(turn_deg, out_degree)) {
658	            kind = route_classify_turn(turn_deg);
659	            if (kind != VMAP_MANEUVER_STRAIGHT || out_degree >= 3u) {
660	                route_maneuver_put(&maneuvers[count], kind, n0, 0.0, turn_deg,
661	                    out_name, out_degree, NULL, out_name);
662	                count++;
663	            }
664	        } else if (out_degree >= 3u) {
665	            route_maneuver_put(&maneuvers[count], VMAP_MANEUVER_STRAIGHT, n0,
666	                0.0, turn_deg, out_name, out_degree, NULL, out_name);
667	            count++;
668	        }
669	    }
670	
671	    for (uint32_t i = 1; i + 1 < path_len && count < cap; i++) {
672	        const uint32_t prev = path_nodes[i - 1];
673	        const uint32_t cur = path_nodes[i];
674	        const uint32_t next = path_nodes[i + 1];
675	        double lon0;
676	        double lat0;
677	        double lon1;
678	        double lat1;
679	        double lon2;
680	        double lat2;
681	        float in_brg;
682	        float out_brg;
683	        float turn_deg;
684	        vmap_graph_edge_t out_edge;
685	        const char * out_name = NULL;
686	        const char * in_name = NULL;
687	        vmap_graph_edge_t in_edge;
688	        uint32_t out_degree;
689	        vmap_maneuver_kind_t kind;
690	
691	        vmap_route_graph_node_lonlat(graph, prev, &lon0, &lat0);
692	        vmap_route_graph_node_lonlat(graph, cur, &lon1, &lat1);
693	        along += vmap_geo_haversine_m(lon0, lat0, lon1, lat1);
694	
695	        vmap_route_graph_node_lonlat(graph, next, &lon2, &lat2);
696	        in_brg = vmap_geo_bearing_deg(lon0, lat0, lon1, lat1);
697	        out_brg = vmap_geo_bearing_deg(lon1, lat1, lon2, lat2);
698	        turn_deg = vmap_geo_angle_delta_deg(in_brg, out_brg);
699	        out_degree = route_graph_out_degree(graph, cur);
700	
701	        if (route_find_edge(graph, cur, next, &out_edge)) {
702	            out_name = vmap_route_graph_edge_name(graph, &out_edge);
703	        }
704	        if (route_find_edge(graph, prev, cur, &in_edge)) {
705	            in_name = vmap_route_graph_edge_name(graph, &in_edge);
706	        }
707	
708	        if (!route_should_emit_maneuver(turn_deg, out_degree)) {
709	            if (in_name && out_name && in_name != out_name
710	                && strcmp(in_name, out_name) != 0
711	                && fabsf(turn_deg) >= VMAP_ROUTE_MANEUVER_JUNCTION_DEG) {
712	                /* name change at a bend */
713	            } else {
714	                continue;
715	            }
716	        }
717	
718	        kind = route_classify_turn(turn_deg);
719	        if (kind == VMAP_MANEUVER_STRAIGHT && out_degree < 3u) {
720	            continue;
721	        }
722	
723	        route_maneuver_put(&maneuvers[count], kind, cur, along, turn_deg,
724	            out_name, out_degree, in_name, out_name);
725	        count++;
726	    }
727	
728	    if (count < cap && path_len >= 2) {
729	        double lon_a;
730	        double lat_a;
731	        double lon_b;
732	        double lat_b;
733	
734	        vmap_route_graph_node_lonlat(graph, path_nodes[path_len - 2], &lon_a,
735	            &lat_a);
736	        vmap_route_graph_node_lonlat(graph, path_nodes[path_len - 1], &lon_b,
737	            &lat_b);
738	        along += vmap_geo_haversine_m(lon_a, lat_a, lon_b, lat_b);
739	
740	        route_maneuver_put(&maneuvers[count], VMAP_MANEUVER_ARRIVE,
741	            path_nodes[path_len - 1], along, 0.0f, NULL, 0, NULL, NULL);
742	        count++;
743	    }
744	
745	    return count;
746	}
747	
748	static bool route_build_result(vmap_route_graph_t * graph, uint32_t src,
749	    uint32_t dst, uint32_t * prev, double from_lon, double from_lat,
750	    vmap_route_pt_t * pts, uint32_t * pt_count,
751	    double * total_m, vmap_route_maneuver_t * maneuvers, uint32_t maneuver_cap,
752	    uint32_t * maneuver_count)
753	{
754	    uint32_t * path_nodes;
755	    uint32_t path_len = 0;
756	    uint32_t cur = dst;
757	    bool ok;
758	
759	    if (!graph || !prev || !pts || !pt_count || !total_m) {
760	        return false;
761	    }
762	
763	    *pt_count = 0;
764	    *total_m = 0.0;
765	    if (maneuver_count) {
766	        *maneuver_count = 0;
767	    }
768	
769	    path_nodes = (uint32_t *)vmap_malloc((size_t)VMAP_ROUTE_MAX_PTS * sizeof(*path_nodes));
770	    if (!path_nodes) {
771	        return false;
772	    }
773	
774	    while (cur != UINT32_MAX && path_len < VMAP_ROUTE_MAX_PTS) {
775	        path_nodes[path_len++] = cur;
776	        if (cur == src) {
777	            break;
778	        }
779	        if (cur >= vmap_route_graph_node_count(graph)) {
780	            break;
781	        }
782	        cur = prev[cur];
783	    }
784	
785	    if (path_len < 2) {
786	        VMAP_NAV_WARN("compute: trivial path src=%u dst=%u len=%u",
787	            src, dst, path_len);
788	        vmap_free(path_nodes);
789	        return false;
790	    }
791	
792	    for (uint32_t i = path_len; i > 0; i--) {
793	        const uint32_t idx = path_nodes[i - 1];
794	
795	        vmap_route_graph_node_lonlat(graph, idx, &pts[*pt_count].lon,
796	            &pts[*pt_count].lat);
797	        pts[*pt_count].ele_m = vmap_route_graph_node_ele_m(graph, idx);
798	        (*pt_count)++;
799	    }
800	
801	    for (uint32_t i = 1; i < *pt_count; i++) {
802	        *total_m += vmap_geo_haversine_m(pts[i - 1].lon, pts[i - 1].lat,
803	            pts[i].lon, pts[i].lat);
804	    }
805	
806	    if (maneuvers && maneuver_cap > 0 && maneuver_count) {
807	        uint32_t * ordered;
808	        uint32_t n_man;
809	
810	        ordered = (uint32_t *)vmap_malloc((size_t)path_len * sizeof(*ordered));
811	        if (ordered) {
812	            for (uint32_t i = 0; i < path_len; i++) {
813	                ordered[i] = path_nodes[path_len - 1u - i];
814	            }
815	            n_man = route_build_maneuvers(graph, ordered, path_len,
816	                from_lon, from_lat, maneuvers, maneuver_cap);
817	            *maneuver_count = n_man;
818	            route_log_maneuvers(maneuvers, n_man);
819	            vmap_free(ordered);
820	        }
821	    }
822	
823	    VMAP_NAV_OUT("path: graph_nodes=%u polyline_pts=%u length=%.0fm",
824	        path_len, *pt_count, *total_m);
825	    route_log_graph_node(graph, "path_start", path_nodes[path_len - 1u]);
826	    route_log_graph_node(graph, "path_end", path_nodes[0]);
827	
828	    ok = *pt_count >= 2;
829	    vmap_free(path_nodes);
830	    return ok;
831	}
