939	/**
940	 * @brief vmap route compute pins。
941	 */
942	/* 把折线**末点**从"最近节点"拉到"请求点在该边上的投影"。
943	 *
944	 * 为什么需要：终点多半落在一段路的中间（显示瓦片里有这条路、有节点画出来的线），
945	 * 但路网图里节点只在端点/路口 —— 于是"取最近节点"会偏 100~200 m，屏幕上表现为
946	 * "到了却不判到达"（现场：偏航 43 m、终点 171 m 外）。投影到边上之后，路线末端
947	 * 就落在你点的位置附近（同一条路上，不会画出一条离开道路的直线）。
948	 * 只动末点、并按差值修正总长；投影不在段内（t 贴边）就不动。 */
949	static void route_pull_end_to_request(vmap_route_pt_t * pts, uint32_t n,
950	    double * total_m, double lon, double lat)
951	{
952	    double t = 0.0;
953	    double seg_old;
954	    double seg_new;
955	    vmap_route_pt_t last;
956	
957	    if (!pts || !total_m || n < 2u) {
958	        return;
959	    }
960	
961	    (void)vmap_geo_point_to_seg_m(lon, lat, pts[n - 2u].lon, pts[n - 2u].lat,
962	        pts[n - 1u].lon, pts[n - 1u].lat, &t);
963	    if (t <= 0.001 || t >= 0.999) {
964	        return;
965	    }
966	
967	    seg_old = vmap_geo_haversine_m(pts[n - 2u].lon, pts[n - 2u].lat,
968	        pts[n - 1u].lon, pts[n - 1u].lat);
969	    last.lon = pts[n - 2u].lon + (pts[n - 1u].lon - pts[n - 2u].lon) * t;
970	    last.lat = pts[n - 2u].lat + (pts[n - 1u].lat - pts[n - 2u].lat) * t;
971	    seg_new = vmap_geo_haversine_m(pts[n - 2u].lon, pts[n - 2u].lat, last.lon,
972	        last.lat);
973	    if (seg_new < 1.0 || seg_new >= seg_old) {
974	        return;
975	    }
976	
977	    pts[n - 1u] = last;
978	    *total_m += (seg_new - seg_old);
979	}
980	
981	bool vmap_route_compute_pins(vmap_route_graph_t * graph,
982	    double from_lon, double from_lat, double to_lon, double to_lat,
983	    uint32_t pin_src, uint32_t pin_dst, vmap_route_pt_t * pts,
984	    uint32_t * pt_count, double * total_m, vmap_route_maneuver_t * maneuvers,
985	    uint32_t maneuver_cap, uint32_t * maneuver_count)
986	{
987	    uint32_t src_cands[VMAP_ROUTE_SNAP_K];
988	    uint32_t dst_cands[VMAP_ROUTE_SNAP_K];
989	    uint32_t n_src;
990	    uint32_t n_dst;
991	    double src_snap_m = 0.0;
992	    double dst_snap_m = 0.0;
993	    uint32_t src;
994	    uint32_t dst;
995	    uint32_t reachable = 0;
996	    uint32_t n_nodes;
997	    uint32_t n_edges;
998	    bool ok;
999	
1000	    if (!graph || !pts || !pt_count || !total_m) {
1001	        VMAP_NAV_ERR("compute: bad args graph=%p pts=%p", (void *)graph, (void *)pts);
1002	        return false;
1003	    }
1004	
1005	    *pt_count = 0;
1006	    *total_m = 0.0;
1007	    if (maneuver_count) {
1008	        *maneuver_count = 0;
1009	    }
1010	
1011	    n_nodes = vmap_route_graph_node_count(graph);
1012	    n_edges = vmap_route_graph_edge_count(graph);
1013	    VMAP_NAV_OUT("compute: graph nodes=%u edges=%u", n_nodes, n_edges);
1014	    {
1015	        const double d = vmap_geo_haversine_m(from_lon, from_lat, to_lon, to_lat);
1016	
1017	        if (d <= VMAP_ROUTE_ARRIVE_M) {
1018	            VMAP_NAV_WARN("compute: already at dest d=%.0fm", d);
1019	            return false;
1020	        }
1021	    }
1022	    vmap_route_plan_yield();
1023	    if (vmap_route_plan_aborted()) {
1024	        return false;
1025	    }
1026	    if (!route_plan_scratch_ensure(n_nodes, n_edges)) {
1027	        return false;
1028	    }
1029	
1030	    VMAP_NAV_OUT("compute: snap start (%.7f,%.7f)", from_lon, from_lat);
1031	    if (pin_src != UINT32_MAX && pin_src < n_nodes
1032	        && vmap_route_graph_node_is_routable(graph, pin_src)) {
1033	        double slon;
1034	        double slat;
1035	
1036	        src_cands[0] = pin_src;
1037	        n_src = 1;
1038	        vmap_route_graph_node_lonlat(graph, pin_src, &slon, &slat);
1039	        src_snap_m = vmap_geo_haversine_m(from_lon, from_lat, slon, slat);
1040	        VMAP_NAV_LOG("compute: pin start node=%u", pin_src);
1041	    } else {
1042	        n_src = vmap_route_graph_snap_end(graph, from_lon, from_lat,
1043	            src_cands, VMAP_ROUTE_SNAP_K, &src_snap_m);
1044	    }
1045	
1046	    VMAP_NAV_OUT("compute: snap dest (%.7f,%.7f)", to_lon, to_lat);
1047	    if (pin_dst != UINT32_MAX && pin_dst < n_nodes
1048	        && vmap_route_graph_node_is_routable(graph, pin_dst)) {
1049	        double dlon;
1050	        double dlat;
1051	
1052	        dst_cands[0] = pin_dst;
1053	        n_dst = 1;
1054	        vmap_route_graph_node_lonlat(graph, pin_dst, &dlon, &dlat);
1055	        dst_snap_m = vmap_geo_haversine_m(to_lon, to_lat, dlon, dlat);
1056	        VMAP_NAV_LOG("compute: pin dest node=%u", pin_dst);
1057	    } else {
1058	        n_dst = vmap_route_graph_snap_end(graph, to_lon, to_lat,
1059	            dst_cands, VMAP_ROUTE_SNAP_K, &dst_snap_m);
1060	    }
1061	
1062	    if (n_src == 0 || n_dst == 0) {
1063	        double from_near = vmap_route_graph_nearest_distance_m(graph, from_lon,
1064	            from_lat, NULL);
1065	        double to_near = vmap_route_graph_nearest_distance_m(graph, to_lon,
1066	            to_lat, NULL);
1067	
1068	        if (n_src == 0 && n_dst == 0) {
1069	            VMAP_NAV_WARN("compute: both ends off-road "
1070	                "from=%.6f,%.6f nearest=%.0fm to=%.6f,%.6f nearest=%.0fm",
1071	                from_lon, from_lat, from_near, to_lon, to_lat, to_near);
1072	        } else if (n_src == 0) {
1073	            VMAP_NAV_WARN("compute: start off-road "
1074	                "from=%.6f,%.6f nearest=%.0fm (dest ok n_dst=%lu)",
1075	                from_lon, from_lat, from_near, (unsigned long)n_dst);
1076	        } else {
1077	            VMAP_NAV_WARN("compute: dest off-road "
1078	                "to=%.6f,%.6f nearest=%.0fm (start ok n_src=%lu)",
1079	                to_lon, to_lat, to_near, (unsigned long)n_src);
1080	        }
1081	        route_plan_scratch_release();
1082	        return false;
1083	    }
1084	
1085	    route_log_snap_cands("start", graph, src_cands, n_src, src_snap_m);
1086	    route_log_snap_cands("dest", graph, dst_cands, n_dst, dst_snap_m);
1087	    vmap_route_plan_yield();
1088	
1089	    n_src = route_drop_shared_src(src_cands, n_src, dst_cands, n_dst);
1090	    if (n_src == 0) {
1091	        VMAP_NAV_WARN("compute: start/dest snap overlap d=%.0fm",
1092	            vmap_geo_haversine_m(from_lon, from_lat, to_lon, to_lat));
1093	        route_plan_scratch_release();
1094	        return false;
1095	    }
1096	
1097	    g_last_snap_src_m = src_snap_m;
1098	    g_last_snap_dst_m = dst_snap_m;
1099	
1100	    if (src_snap_m > VMAP_ROUTE_SNAP_M || dst_snap_m > VMAP_ROUTE_SNAP_M) {
1101	        VMAP_NAV_OUT("compute: snap expanded start=%.0fm dest=%.0fm",
1102	            src_snap_m, dst_snap_m);
1103	    }
1104	
1105	    VMAP_NAV_OUT("compute: Dijkstra seeds src=%u dst_lead=%u",
1106	        src_cands[0], dst_cands[0]);
1107	    ok = route_search_targets(graph, src_cands, n_src, dst_cands, n_dst,
1108	        g_plan_scratch.prev, &src, &dst, &reachable);
1109	    if (ok) {
1110	        ok = route_build_result(graph, src, dst, g_plan_scratch.prev,
1111	            from_lon, from_lat, pts, pt_count, total_m, maneuvers, maneuver_cap,
1112	            maneuver_count);
1113	
1114	        /* 折线首尾补上**请求的起终点**：snap 只吸到最近的"图节点"，而这张图的节点很稀
1115	         * （边可长达 500 m+），于是路线会在离终点最多半条边长的地方就断掉 —— 屏幕上
1116	         * 就是"轨迹线缺一段/离路"（实测终点偏 167 m）。这里在首尾各接一小段到真实
1117	         * 起终点，让线走到该走的位置；与节点重合（<1 m）时不加。 */
1118	        if (ok && pts && pt_count && *pt_count >= 2u) {
1119	            if (src_snap_m > 1.0 && src_snap_m <= VMAP_ROUTE_SNAP_MAX_M
1120	                && *pt_count + 1u <= VMAP_ROUTE_MAX_PTS) {
1121	                uint32_t k;
1122	
1123	                for (k = *pt_count; k > 0u; k--) {
1124	                    pts[k] = pts[k - 1u];
1125	                }
1126	                pts[0].lon = from_lon;
1127	                pts[0].lat = from_lat;
1128	                pts[0].ele_m = pts[1].ele_m;
1129	                (*pt_count)++;
1130	                *total_m += src_snap_m;
1131	            }
1132	            if (dst_snap_m > 1.0 && dst_snap_m <= VMAP_ROUTE_SNAP_MAX_M
1133	                && *pt_count + 1u <= VMAP_ROUTE_MAX_PTS) {
1134	                pts[*pt_count].lon = to_lon;
1135	                pts[*pt_count].lat = to_lat;
1136	                pts[*pt_count].ele_m = pts[*pt_count - 1u].ele_m;
1137	                (*pt_count)++;
1138	                *total_m += dst_snap_m;
1139	            }
1140	        }
1141	        if (ok) {
1142	            /* 末点投到请求点所在的边上（见 route_pull_end_to_request） */
1143	            route_pull_end_to_request(pts, *pt_count, total_m, to_lon, to_lat);
1144	            VMAP_NAV_OUT("compute: ok pts=%u man=%u len=%.0fm",
1145	                *pt_count,
1146	                maneuver_count ? *maneuver_count : 0u,
1147	                *total_m);
1148	        } else {
1149	            VMAP_NAV_WARN("compute: build failed src=%u dst=%u", src, dst);
1150	            ok = false;
1151	        }
1152	    } else {
1153	        double slon = 0.0;
1154	        double slat = 0.0;
1155	        double dlon = 0.0;
1156	        double dlat = 0.0;
1157	
1158	        vmap_route_graph_node_lonlat(graph, src_cands[0], &slon, &slat);
1159	        vmap_route_graph_node_lonlat(graph, dst_cands[0], &dlon, &dlat);
1160	        VMAP_NAV_WARN("compute: no path lead_src=%u(%.6f,%.6f) routable=%d "
1161	            "lead_dst=%u(%.6f,%.6f) reachable=%lu/%u",
1162	            src_cands[0], slon, slat,
1163	            vmap_route_graph_node_is_routable(graph, src_cands[0]) ? 1 : 0,
1164	            dst_cands[0], dlon, dlat,
1165	            (unsigned long)reachable, vmap_route_graph_node_count(graph));
1166	    }
1167	    return ok;
1168	}
