1184	/**
1185	 * @brief vmap route apply。
1186	 */
1187	void vmap_route_apply(vmap_route_t * route, const vmap_route_pt_t * pts,
1188	    uint32_t pt_count, double total_m,
1189	    const vmap_route_maneuver_t * maneuvers, uint32_t maneuver_count)
1190	{
1191	    if (!route) {
1192	        return;
1193	    }
1194	
1195	    route->active = false;
1196	    route->pt_count = 0;
1197	    route->total_m = 0.0;
1198	    route->maneuver_count = 0;
1199	
1200	    if (!pts || pt_count < 2 || pt_count > VMAP_ROUTE_MAX_PTS) {
1201	        VMAP_NAV_WARN("apply: rejected pts=%u", pt_count);
1202	        return;
1203	    }
1204	
1205	    memcpy(route->pts, pts, (size_t)pt_count * sizeof(route->pts[0]));
1206	    route->pt_count = pt_count;
1207	    route->total_m = total_m;
1208	    route->active = true;
1209	
1210	    if (maneuvers && maneuver_count > 0) {
1211	        if (maneuver_count > VMAP_ROUTE_MAX_MANEUVERS) {
1212	            maneuver_count = VMAP_ROUTE_MAX_MANEUVERS;
1213	        }
1214	        memcpy(route->maneuvers, maneuvers,
1215	            (size_t)maneuver_count * sizeof(route->maneuvers[0]));
1216	        route->maneuver_count = maneuver_count;
1217	    }
1218	
1219	    VMAP_NAV_LOG("apply: active pts=%u man=%u len=%.0fm",
1220	        pt_count, route->maneuver_count, total_m);
1221	    route->progress_valid = false;
1222	    if (route->progress_pos_seen) {
1223	        /* 重规划换了几何：立刻用上一次的位置把"已骑段"重新标出来，
1224	         * 否则 progress 一直是 invalid，绘制退化成全蓝（用户看到的就是这个）。 */
1225	        vmap_route_set_progress_pos(route, route->progress_lon,
1226	            route->progress_lat);
1227	    }
1228	    route->review = false;
1229	}
