1231	/**
1232	 * @brief vmap route splice forward。
1233	 */
1234	bool vmap_route_splice_forward(vmap_route_t * route, double lon, double lat,
1235	    const vmap_route_pt_t * new_pts, uint32_t new_n, double new_total_m,
1236	    const vmap_route_maneuver_t * new_man, uint32_t new_man_n)
1237	{
1238	    vmap_route_pt_t * merged;
1239	    vmap_route_maneuver_t * merged_man;
1240	    uint32_t merged_n = 0;
1241	    uint32_t merged_man_n = 0;
1242	    uint32_t start_i = 0;
1243	    uint32_t i;
1244	    double kept_m = 0.0;
1245	
1246	    if (!route || !new_pts || new_n < 2 || new_n > VMAP_ROUTE_MAX_PTS) {
1247	        return false;
1248	    }
1249	
1250	    /* Rare reroute path: these two arrays are ~50 KiB and must not live on
1251	     * bicycle_ui's SRAM stack. vmap_malloc is the BoardPSRAM allocator. */
1252	    merged = (vmap_route_pt_t *)vmap_malloc(
1253	        (size_t)VMAP_ROUTE_MAX_PTS * sizeof(*merged));
1254	    merged_man = (vmap_route_maneuver_t *)vmap_malloc(
1255	        (size_t)VMAP_ROUTE_MAX_MANEUVERS * sizeof(*merged_man));
1256	    if (merged == NULL || merged_man == NULL) {
1257	        vmap_free(merged);
1258	        vmap_free(merged_man);
1259	        return false;
1260	    }
1261	
1262	    vmap_route_set_progress_pos(route, lon, lat);
1263	
1264	    for (i = 0; i <= route->progress_seg && i < route->pt_count; i++) {
1265	        merged[merged_n++] = route->pts[i];
1266	    }
1267	    if (merged_n < VMAP_ROUTE_MAX_PTS) {
1268	        merged[merged_n].lon = route->progress_lon;
1269	        merged[merged_n].lat = route->progress_lat;
1270	        merged[merged_n].ele_m = (int16_t)VGRF_ELE_UNKNOWN;
1271	        merged_n++;
1272	    }
1273	
1274	    if (merged_n > 0 && new_n > 0) {
1275	        const double d = vmap_geo_haversine_m(merged[merged_n - 1u].lon,
1276	            merged[merged_n - 1u].lat, new_pts[0].lon, new_pts[0].lat);
1277	
1278	        if (d < VMAP_ROUTE_STITCH_DEDUP_M) {
1279	            start_i = 1;
1280	        }
1281	    }
1282	
1283	    for (i = start_i; i < new_n && merged_n < VMAP_ROUTE_MAX_PTS; i++) {
1284	        merged[merged_n++] = new_pts[i];
1285	    }
1286	
1287	    if (merged_n < 2) {
1288	        vmap_free(merged);
1289	        vmap_free(merged_man);
1290	        return false;
1291	    }
1292	
1293	    for (i = 1; i < merged_n; i++) {
1294	        kept_m += vmap_geo_haversine_m(merged[i - 1u].lon, merged[i - 1u].lat,
1295	            merged[i].lon, merged[i].lat);
1296	    }
1297	
1298	    if (new_man && new_man_n > 0) {
1299	        for (i = 0; i < new_man_n && merged_man_n < VMAP_ROUTE_MAX_MANEUVERS; i++) {
1300	            if (new_man[i].kind == VMAP_MANEUVER_START) {
1301	                continue;
1302	            }
1303	            merged_man[merged_man_n] = new_man[i];
1304	            merged_man[merged_man_n].along_m += kept_m - new_total_m;
1305	            merged_man_n++;
1306	        }
1307	    }
1308	
1309	    vmap_route_apply(route, merged, merged_n, kept_m, merged_man, merged_man_n);
1310	    vmap_route_set_progress_pos(route, lon, lat);
1311	    vmap_free(merged);
1312	    vmap_free(merged_man);
1313	    return true;
1314	}
