1316	/**
1317	 * @brief vmap route set progress pos。
1318	 */
1319	void vmap_route_set_progress_match(vmap_route_t * route, double lon, double lat,
1320	    uint32_t seg, double seg_t)
1321	{
1322	    if (!route || !vmap_route_is_active(route)
1323	        || seg + 1u >= route->pt_count) {
1324	        return;
1325	    }
1326	
1327	    if (seg_t < 0.0) {
1328	        seg_t = 0.0;
1329	    } else if (seg_t > 1.0) {
1330	        seg_t = 1.0;
1331	    }
1332	
1333	    route->progress_pos_seen = true;
1334	    route->anchor_lon = lon;
1335	    route->anchor_lat = lat;
1336	    route->progress_seg = seg;
1337	    route->progress_lon = route->pts[seg].lon
1338	        + (route->pts[seg + 1u].lon - route->pts[seg].lon) * seg_t;
1339	    route->progress_lat = route->pts[seg].lat
1340	        + (route->pts[seg + 1u].lat - route->pts[seg].lat) * seg_t;
1341	    route->progress_valid = true;
1342	}
1343	
1344	void vmap_route_set_progress_pos(vmap_route_t * route, double lon, double lat)
1345	{
1346	    const vmap_route_pt_t * pts;
1347	    uint32_t n;
1348	    uint32_t start;
1349	    uint32_t best_seg = 0;
1350	    double best_t = 0.0;
1351	    double best_d = 1e18;
1352	
1353	    if (!route || !vmap_route_is_active(route)) {
1354	        return;
1355	    }
1356	
1357	    route->progress_pos_seen = true;
1358	
1359	    pts = route->pts;
1360	    n = route->pt_count;
1361	    start = route->progress_valid && route->progress_seg > 1u
1362	        ? route->progress_seg - 1u : 0u;
1363	
1364	    for (uint32_t i = start; i + 1u < n; i++) {
1365	        double t = 0.0;
1366	        const double d = vmap_geo_point_to_seg_m(lon, lat,
1367	            pts[i].lon, pts[i].lat, pts[i + 1u].lon, pts[i + 1u].lat, &t);
1368	
1369	        if (d < best_d) {
1370	            best_d = d;
1371	            best_seg = i;
1372	            best_t = t;
1373	        }
1374	    }
1375	
1376	    vmap_route_set_progress_match(route, lon, lat, best_seg, best_t);
1377	}
