1382	double vmap_route_effective_along_m(const vmap_route_t * route,
1383	    double polyline_along_m)
1384	{
1385	    double connector_m;
1386	
1387	    if (!route || !route->progress_valid) {
1388	        return polyline_along_m;
1389	    }
1390	
1391	    connector_m = vmap_geo_haversine_m(route->anchor_lon, route->anchor_lat,
1392	        route->progress_lon, route->progress_lat);
1393	    if (connector_m > 2.0 && polyline_along_m < connector_m + 5.0) {
1394	        return polyline_along_m - connector_m;
1395	    }
1396	    return polyline_along_m;
