1399	static bool route_px_keep(int32_t x0, int32_t y0, int32_t x1, int32_t y1,
1400	    bool force)
1401	{
1402	    const int32_t dx = x1 - x0;
1403	    const int32_t dy = y1 - y0;
1404	    const int32_t min2 = VMAP_ROUTE_DRAW_MIN_PX * VMAP_ROUTE_DRAW_MIN_PX;
1405	
1406	    if (force) {
1407	        return (dx != 0) || (dy != 0);
1408	    }
1409	    return (dx * dx + dy * dy) >= min2;
1410	}
