1421	static void route_append_geo(const vmap_view_t * view, vmap_point_t * out,
1422	    int32_t * n, int32_t cap, double lon, double lat, bool force)
1423	{
1424	    int32_t x;
1425	    int32_t y;
1426	    int32_t cw;
1427	    int32_t ch;
1428	    int64_t max_jump2;
1429	
1430	    if (!view || !out || !n || cap < 2) {
1431	        return;
1432	    }
1433	    if (!vmap_view_geo_to_canvas_raw(view, lon, lat, &x, &y)) {
1434	        return;
1435	    }
1436	    if (!vmap_view_canvas_point_in_pad(view, x, y, 64)) {
1437	        return;
1438	    }
1439	
1440	    if (*n > 0) {
1441	        const int32_t px = out[*n - 1].x;
1442	        const int32_t py = out[*n - 1].y;
1443	
1444	        if (!route_px_keep(px, py, x, y, force || (*n + 1 >= cap))) {
1445	            return;
1446	        }
1447	
1448	        vmap_view_get_buffer_size(view, &cw, &ch);
1449	        max_jump2 = (int64_t)(cw > ch ? cw : ch);
1450	        max_jump2 *= max_jump2;
1451	        {
1452	            const int64_t dx = (int64_t)x - (int64_t)px;
1453	            const int64_t dy = (int64_t)y - (int64_t)py;
1454	
1455	            if (dx * dx + dy * dy > max_jump2) {
1456	                return;
1457	            }
1458	        }
1459	    }
1460	
1461	    if (*n >= cap) {
1462	        out[cap - 1].x = x;
1463	        out[cap - 1].y = y;
1464	        return;
1465	    }
1466	    out[*n].x = x;
1467	    out[*n].y = y;
1468	    (*n)++;
1469	}
