1471	/* 运行方向标的间距与形状（屏幕像素；见 route_paint_geo_range 里的调用）。
1472	 * 定位用**点序号**（每 N 个点一个）而不是累积屏幕距离 —— 后者依赖绘制范围起点，
1473	 * 切页回来起点微动就会落在差几像素的位置，旧墨迹没人擦、看起来"每切一次多一个"
1474	 * （用户 2026-09-25）。点序号与起点无关，重绘像素完全一致，天然幂等。
1475	 * 点距约 13.6 m ⇒ 每 18 点约 245 m，折算到当前缩放约 48 px，观感与之前一致。 */
1476	#define VMAP_ROUTE_CHEVRON_EVERY   18
1477	#define VMAP_ROUTE_CHEVRON_ARM_PX  8
1478	#define VMAP_ROUTE_CHEVRON_DEG     44.0
1479	
1480	/** @brief 沿屏幕方向画一个黑色 "^"：两臂各偏 ±35°、长 5 px、线宽 2。 */
1481	/**
1482	 * @brief 方向指示（"^" 瓦片）的颜色：日光=**黑**（一直是这个），夜间=**橙**。
1483	 *
1484	 * @note 用户 2026-09-27 定：黑的 ^ 在夜间那份深色地图上完全看不见 ⇒ 夜间改橙 #FF6E12
1485	 *       （RGB565 0xFB62）；日光保持原来的黑（浅色底上黑最清楚，也不必和蓝色路线较劲）。
1486	 *       判据与路线取色同源（地图风格，night = 夜间）。
1487	 * @return RGB565。
1488	 */
1489	static uint16_t route_chevron_rgb(void)
1490	{
1491	    return (vmap_style_get_id() == VMAP_STYLE_NIGHT) ? (uint16_t)0xFB62u
1492	                                                      : (uint16_t)0x0000u;
1493	}
