1495	static void route_draw_chevron(vmap_canvas_t * canvas, int32_t x, int32_t y,
1496	    double ang_rad)
1497	{
1498	    const double half = VMAP_ROUTE_CHEVRON_DEG * (3.14159265358979323846 / 180.0);
1499	    int s;
1500	
1501	    for (s = -1; s <= 1; s += 2) {
1502	        const double a = ang_rad + 3.14159265358979323846 + (double)s * half;
1503	        vmap_point_t arm[2];
1504	
1505	        arm[0].x = x;
1506	        arm[0].y = y;
1507	        arm[1].x = (int32_t)((double)x + cos(a) * VMAP_ROUTE_CHEVRON_ARM_PX + 0.5);
1508	        arm[1].y = (int32_t)((double)y + sin(a) * VMAP_ROUTE_CHEVRON_ARM_PX + 0.5);
1509	        /* 方向指示（"^"）：日光黑、夜间橙 —— 见 route_chevron_rgb() 的注释。 */
1510	        vmap_render_stroke_ribbon(canvas, arm, 2, 2, route_chevron_rgb());
1511	    }
1512	}
