1514	/**
1515	 * @brief 导航线（未走过部分）的颜色：日光=蓝，夜间（深色地图）=**亮绿**。
1516	 *
1517	 * @note 用户 2026-09-27：夜间那份地图的水面也是蓝的，蓝色路线和水面糊在一起 ⇒ 夜间改亮绿。
1518	 *       判据用**地图风格**（night = 夜间深色地图，见 bicycle_pm_theme.c 的映射），
1519	 *       与其它取色同源；日光仍走 `VMAP_ROUTE_LINE_RGB565`。
1520	 * @return RGB565。
1521	 */
1522	static uint16_t route_line_rgb(void)
1523	{
1524	    /* #00E676（Material 亮绿）⇒ RGB565：r=0<<11 | g=(230>>2)<<5 | b=(118>>3) = 0x072E */
1525	    return (vmap_style_get_id() == VMAP_STYLE_NIGHT) ? (uint16_t)0x072Eu
1526	                                                      : VMAP_ROUTE_LINE_RGB565;
1527	}
