1529	/* —— 路线/箭头的擦除记账 ——
1530	 * 覆盖层是烘进常驻画布的：瓦片重贴会盖掉线（该补画），但**几何跳变**（GPX 窗口续载、
1531	 * 跟车重锚、容器尺寸变化）会让旧位置的墨迹没人擦，留下残影（用户 2026-09-25 实测：
1532	 * "每进一次地图就多烘一份"）。做法与路名标注一致：记下这一帧画过的屏幕框与分割点，
1533	 * 下一次发现分割点**跳变**就把旧框并进脏区，让瓦片在那儿重贴一遍。
1534	 * 只在跳变时发生（不是每拍），所以代价可控。 */
1535	static lv_area_t s_route_box;
1536	static int32_t   s_route_split_x;
1537	static int32_t   s_route_split_y;
1538	static bool      s_route_box_valid;
1539	
1540	static void route_note_box(lv_area_t * box, int32_t x1, int32_t y1, int32_t x2,
1541	    int32_t y2)
1542	{
1543	    if (x1 > x2) {
1544	        const int32_t t = x1;
1545	
1546	        x1 = x2;
1547	        x2 = t;
1548	    }
1549	    if (y1 > y2) {
1550	        const int32_t t = y1;
1551	
1552	        y1 = y2;
1553	        y2 = t;
1554	    }
1555	    box->x1 = (box->x1 < x1) ? box->x1 : x1;
1556	    box->y1 = (box->y1 < y1) ? box->y1 : y1;
1557	    box->x2 = (box->x2 > x2) ? box->x2 : x2;
1558	    box->y2 = (box->y2 > y2) ? box->y2 : y2;
1559	}
