1561	static void route_paint_geo_range(const vmap_view_t * view, vmap_canvas_t * canvas,
1562	    const vmap_route_pt_t * pts, uint32_t begin, uint32_t end,
1563	    double extra_lon, double extra_lat, bool extra_first, uint16_t rgb565)
1564	{
1565	    vmap_point_t px[256];
1566	    int32_t n = 0;
1567	    uint32_t i;
1568	
1569	    if (!view || !canvas || !pts || end < 2u || begin + 1u > end) {
1570	        return;
1571	    }
1572	
1573	    lv_area_t new_box = { INT32_MAX, INT32_MAX, INT32_MIN, INT32_MIN };
1574	    const bool chevrons = extra_first;
1575	
1576	    if (extra_first) {
1577	        route_append_geo(view, px, &n, (int32_t)(sizeof(px) / sizeof(px[0])),
1578	            extra_lon, extra_lat, true);
1579	    }
1580	
1581	    for (i = begin; i < end; i++) {
1582	        const bool last = (i + 1u == end);
1583	        const int32_t before = n;
1584	
1585	        route_append_geo(view, px, &n, (int32_t)(sizeof(px) / sizeof(px[0])),
1586	            pts[i].lon, pts[i].lat, last);
1587	
1588	        if (n > before && n >= 2) {
1589	            const int32_t k = n - 1;
1590	            const double dx = (double)(px[k].x - px[k - 1].x);
1591	            const double dy = (double)(px[k].y - px[k - 1].y);
1592	            const double len = sqrt(dx * dx + dy * dy);
1593	
1594	            /* 方向箭头与蓝线在**同一次绘制**里烘焙（用户 2026-09-25），位置按点序号取，
1595	             * 与绘制范围起点无关 ⇒ 重绘幂等，切页回来不会再冒出一个箭头。 */
1596	            if (chevrons && (i % VMAP_ROUTE_CHEVRON_EVERY) == 0u && len >= 1.0) {
1597	                route_draw_chevron(canvas, px[k].x, px[k].y, atan2(dy, dx));
1598	            }
1599	            route_note_box(&new_box, px[k - 1].x, px[k - 1].y, px[k].x, px[k].y);
1600	        }
1601	    }
1602	
1603	    route_stroke_px(canvas, px, n, rgb565);
1604	
1605	    if (extra_first && n >= 2) {
1606	        /* 分割点跳变判定：以路线起点（骑手位置投影）为准，阈值取半个屏宽 ——
1607	         * 小于它的移动都属于跟车滚动，滚动脏条已经覆盖。 */
1608	        const int32_t sx = px[0].x;
1609	        const int32_t sy = px[0].y;
1610	        int32_t jx = sx - s_route_split_x;
1611	        int32_t jy = sy - s_route_split_y;
1612	
1613	        if (jx < 0) {
1614	            jx = -jx;
1615	        }
1616	        if (jy < 0) {
1617	            jy = -jy;
1618	        }
1619	        if (s_route_box_valid && (jx > 120 || jy > 120)) {
1620	            vmap_view_invalidate_canvas_area(view, s_route_box.x1, s_route_box.y1,
1621	                s_route_box.x2, s_route_box.y2);
1622	        }
1623	        if (new_box.x2 >= new_box.x1) {
1624	            s_route_box = new_box;
1625	            s_route_box_valid = true;
1626	        }
1627	        s_route_split_x = sx;
1628	        s_route_split_y = sy;
1629	    }
1630	}
