1632	static void route_history_append_pt(vmap_route_t * route, double lon, double lat)
1633	{
1634	    vmap_route_pt_t * dst;
1635	
1636	    if (!route || route->history_count >= VMAP_ROUTE_MAX_PTS) {
1637	        return;
1638	    }
1639	    if (route->history_count > 0u) {
1640	        const vmap_route_pt_t * last = &route->history_pts[route->history_count - 1u];
1641	
1642	        if (vmap_geo_haversine_m(last->lon, last->lat, lon, lat) < 2.0) {
1643	            return;
1644	        }
1645	    }
1646	    dst = &route->history_pts[route->history_count++];
1647	    dst->lon = lon;
1648	    dst->lat = lat;
1649	    dst->ele_m = (int16_t)VGRF_ELE_UNKNOWN;
