1652	/**
1653	 * @brief vmap route capture ridden history。
1654	 */
1655	void vmap_route_capture_ridden_history(vmap_route_t * route, double along_m,
1656	    double lon, double lat)
1657	{
1658	    const vmap_route_pt_t * pts;
1659	    uint32_t n;
1660	    double acc = 0.0;
1661	    uint32_t i;
1662	
1663	    if (!route || !vmap_route_is_active(route) || along_m <= 0.0) {
1664	        return;
1665	    }
1666	
1667	    if (route->progress_valid) {
1668	        lon = route->progress_lon;
1669	        lat = route->progress_lat;
1670	    }
1671	
1672	    pts = route->pts;
1673	    n = route->pt_count;
1674	    if (n < 2u) {
1675	        route_history_append_pt(route, lon, lat);
1676	        return;
1677	    }
1678	
1679	    if (route->history_count == 0u) {
1680	        route_history_append_pt(route, pts[0].lon, pts[0].lat);
1681	    }
1682	
1683	    for (i = 0; i + 1u < n && acc < along_m - 0.5; i++) {
1684	        const double seg_m = vmap_geo_haversine_m(pts[i].lon, pts[i].lat,
1685	            pts[i + 1u].lon, pts[i + 1u].lat);
1686	
1687	        if (acc + seg_m <= along_m + 0.5) {
1688	            route_history_append_pt(route, pts[i + 1u].lon, pts[i + 1u].lat);
1689	            acc += seg_m;
1690	        } else {
1691	            break;
1692	        }
1693	    }
1694	    route_history_append_pt(route, lon, lat);
1695	    VMAP_NAV_LOG("ridden history pts=%lu along=%.0fm",
1696	        (unsigned long)route->history_count, along_m);
1697	}
