1770	static int16_t route_ele_on_seg(const vmap_route_pt_t * a, const vmap_route_pt_t * b,
1771	    double seg, double along_on_seg)
1772	{
1773	    if (!a || !b) {
1774	        return (int16_t)VGRF_ELE_UNKNOWN;
1775	    }
1776	    if (!route_ele_known(a->ele_m) && !route_ele_known(b->ele_m)) {
1777	        return (int16_t)VGRF_ELE_UNKNOWN;
1778	    }
1779	    if (!route_ele_known(a->ele_m)) {
1780	        return b->ele_m;
1781	    }
1782	    if (!route_ele_known(b->ele_m) || seg < 0.5) {
1783	        return a->ele_m;
1784	    }
1785	    {
1786	        double t = along_on_seg / seg;
1787	
1788	        if (t < 0.0) {
1789	            t = 0.0;
1790	        } else if (t > 1.0) {
1791	            t = 1.0;
1792	        }
1793	        return (int16_t)lround((double)a->ele_m
1794	            + t * ((double)b->ele_m - (double)a->ele_m));
1795	    }
1796	}
1797	
1798	static bool route_ele_at_along(const vmap_route_pt_t * pts, uint32_t n,
1799	    double along_m, int16_t * out)
1800	{
1801	    double acc = 0.0;
1802	    uint32_t i;
1803	
1804	    if (!pts || n < 2 || !out) {
1805	        return false;
1806	    }
1807	    if (along_m <= 0.0) {
1808	        if (!route_ele_known(pts[0].ele_m)) {
1809	            return false;
1810	        }
1811	        *out = pts[0].ele_m;
1812	        return true;
1813	    }
1814	    for (i = 0; i + 1u < n; i++) {
1815	        const double seg = vmap_geo_haversine_m(pts[i].lon, pts[i].lat,
1816	            pts[i + 1u].lon, pts[i + 1u].lat);
1817	
1818	        if (acc + seg >= along_m || i + 2u >= n) {
1819	            if (!route_ele_known(pts[i].ele_m) || !route_ele_known(pts[i + 1u].ele_m)) {
1820	                if (route_ele_known(pts[i].ele_m)) {
1821	                    *out = pts[i].ele_m;
1822	                    return true;
1823	                }
1824	                if (route_ele_known(pts[i + 1u].ele_m)) {
1825	                    *out = pts[i + 1u].ele_m;
1826	                    return true;
1827	                }
1828	                return false;
1829	            }
1830	            if (seg < 0.5) {
1831	                *out = pts[i].ele_m;
1832	            } else {
1833	                const double t = (along_m - acc) / seg;
1834	                const double clamped = t < 0.0 ? 0.0 : (t > 1.0 ? 1.0 : t);
1835	
1836	                *out = (int16_t)lround((double)pts[i].ele_m
1837	                    + clamped * ((double)pts[i + 1u].ele_m - (double)pts[i].ele_m));
1838	            }
1839	            return true;
1840	        }
1841	        acc += seg;
1842	    }
