1850	int32_t vmap_route_remain_gain_m(const vmap_route_t * route, double along_m)
1851	{
1852	    const vmap_route_pt_t * pts;
1853	    uint32_t n;
1854	    uint32_t i;
1855	    double acc = 0.0;
1856	    int16_t prev = (int16_t)VGRF_ELE_UNKNOWN;
1857	    int32_t gain = 0;
1858	    bool any = false;
1859	    bool in_remain = false;
1860	
1861	    if (!route || !vmap_route_is_active(route)) {
1862	        return -1;
1863	    }
1864	    n = route->pt_count;
1865	    pts = route->pts;
1866	    if (n < 2) {
1867	        return -1;
1868	    }
1869	    if (along_m < 0.0) {
1870	        along_m = 0.0;
1871	    }
1872	
1873	    for (i = 0; i + 1u < n; i++) {
1874	        const double seg = vmap_geo_haversine_m(pts[i].lon, pts[i].lat,
1875	            pts[i + 1u].lon, pts[i + 1u].lat);
1876	        const double end = acc + seg;
1877	
1878	        if (!in_remain && (end > along_m + 0.5 || i + 2u >= n)) {
1879	            double t_m = along_m - acc;
1880	
1881	            in_remain = true;
1882	            prev = route_ele_on_seg(&pts[i], &pts[i + 1u], seg, t_m);
1883	            if (route_ele_known(prev)) {
1884	                any = true;
1885	            }
1886	        }
1887	        if (in_remain && route_ele_known(pts[i + 1u].ele_m)) {
1888	            if (route_ele_known(prev) && pts[i + 1u].ele_m > prev) {
1889	                gain += (int32_t)pts[i + 1u].ele_m - (int32_t)prev;
1890	            }
1891	            prev = pts[i + 1u].ele_m;
1892	            any = true;
1893	        }
1894	        acc = end;
1895	    }
1896	    return any ? gain : -1;
1897	}
