1899	uint32_t vmap_route_profile_ele_span(const vmap_route_t * route,
1900	    double from_m, double to_m, int16_t * out, uint32_t cap)
1901	{
1902	    uint32_t filled = 0;
1903	    uint32_t k;
1904	    double span;
1905	    double total;
1906	
1907	    if (!route || !out || cap == 0 || !vmap_route_is_active(route)) {
1908	        return 0;
1909	    }
1910	    total = route->total_m;
1911	    if (from_m < 0.0) {
1912	        from_m = 0.0;
1913	    }
1914	    if (to_m > total) {
1915	        to_m = total;
1916	    }
1917	    if (to_m < from_m) {
1918	        to_m = from_m;
1919	    }
1920	    span = to_m - from_m;
1921	    if (span < 1.0) {
1922	        int16_t e;
1923	
1924	        if (route_ele_at_along(route->pts, route->pt_count, from_m, &e)) {
1925	            out[0] = e;
1926	            return 1;
1927	        }
1928	        return 0;
1929	    }
1930	
1931	    /* One polyline walk (O(N)), not haversine-per-sample (O(N*cap)). */
1932	    {
1933	        const vmap_route_pt_t * pts = route->pts;
1934	        const uint32_t npts = route->pt_count;
1935	        uint32_t i;
1936	        double acc = 0.0;
1937	        int16_t last_e = (int16_t)VGRF_ELE_UNKNOWN;
1938	        bool have_e = false;
1939	
1940	        k = 0;
1941	        for (i = 0; i + 1u < npts && k < cap; i++) {
1942	            const double seg = vmap_geo_haversine_m(pts[i].lon, pts[i].lat,
1943	                pts[i + 1u].lon, pts[i + 1u].lat);
1944	            const double end = acc + seg;
1945	
1946	            while (k < cap) {
1947	                const double sample_m = (cap == 1u) ? from_m
1948	                    : from_m + span * ((double)k / (double)(cap - 1u));
1949	                int16_t e;
1950	
1951	                if (sample_m > end + 1e-4 && i + 2u < npts) {
1952	                    break;
1953	                }
1954	                e = route_ele_on_seg(&pts[i], &pts[i + 1u], seg, sample_m - acc);
1955	                if (route_ele_known(e)) {
1956	                    last_e = e;
1957	                    have_e = true;
1958	                } else if (have_e) {
1959	                    e = last_e;
1960	                }
1961	                out[k++] = e;
1962	            }
1963	            acc = end;
1964	        }
1965	        while (k < cap) {
1966	            out[k++] = have_e ? last_e : (int16_t)VGRF_ELE_UNKNOWN;
1967	        }
1968	        filled = k;
1969	    }
1970	    if (filled == cap) {
1971	        uint32_t known = 0;
1972	
1973	        for (k = 0; k < cap; k++) {
1974	            if (route_ele_known(out[k])) {
1975	                known++;
1976	            }
1977	        }
1978	        if (known == 0) {
1979	            return 0;
1980	        }
1981	    }
1982	    return filled;
1983	}
