#include <stdio.h>
#include <math.h>
#include <stdint.h>
#define STEP 250.0
#define MAXC 24
typedef struct { int32_t x, y; } pt_t;
/* px spacing arbitrary: 1 px per 2 m to mimic zoomed-out */
static void sim(const double *along, int n, uint32_t begin, double extra_along,
                int extra_first, double px_per_m, const char *tag)
{
    pt_t px[256]; double ang[MAXC]; pt_t ch[MAXC];
    int chev_n = 0; double prev_along = 0.0, next_mark = 0.0; int32_t np = 0;
    /* extra point at along=extra_along maps to x = extra_along*px_per_m */
    if (extra_first) { px[0].x = (int32_t)lround(extra_along*px_per_m); px[0].y = 0; np = 1; }
    if (extra_first) {
        prev_along = extra_along;
        next_mark = ceil(prev_along/STEP)*STEP;
        if (next_mark <= prev_along) next_mark += STEP;
    } else if (begin > 0u) prev_along = along[begin-1u];
    for (uint32_t i = begin; i < (uint32_t)n; i++) {
        int32_t before = np;
        px[np].x = (int32_t)lround(along[i]*px_per_m); px[np].y = 0; np++;
        if (np > before && np >= 2) {
            int32_t k = np-1;
            double dx = px[k].x - px[k-1].x, dy = px[k].y - px[k-1].y;
            double seg_m = (double)along[i] - prev_along;
            while (chev_n < MAXC && next_mark <= along[i]) {
                double t = (seg_m > 0.0) ? (next_mark - prev_along)/seg_m : 1.0;
                if (t < 0.0) t = 0.0; else if (t > 1.0) t = 1.0;
                ch[chev_n].x = px[k-1].x + (int32_t)lround(dx*t);
                ch[chev_n].y = px[k-1].y + (int32_t)lround(dy*t);
                ang[chev_n] = atan2(dy,dx);
                chev_n++; next_mark += STEP;
            }
            prev_along = (double)along[i];
        }
    }
    printf("%s: chev_n=%d marks(along m):", tag, chev_n);
    for (int i = 0; i < chev_n; i++) printf(" %.1f", (double)ch[i].x/px_per_m);
    printf("\n");
}
int main(void)
{
    double a_sparse[] = {0, 400, 800, 1200};              /* 4-pt sparse GPX */
    double a_dense[41];                                    /* 13.6m spacing */
    for (int i = 0; i <= 40; i++) a_dense[i] = i * 13.6;
    sim(a_sparse, 4, 0, 0, 0, 0.05, "sparse fallback(begin0,no extra)");
    sim(a_sparse, 4, 1, 130.0, 1, 0.05, "sparse seg-branch progress=130m");
    sim(a_sparse, 4, 3, 700.0, 1, 0.05, "sparse seg-branch progress=700m");
    sim(a_dense, 41, 0, 0, 0, 0.05, "dense fallback");
    sim(a_dense, 41, 20, 270.0, 1, 0.05, "dense seg-branch progress=270m");
    return 0;
}
